-- Orcha SQLite baseline schema (GH #258, plan D10). GENERATED by
-- tools/db/gen_sqlite_baseline.py from a Postgres database with all
-- 71 templates/migrations/*.sql applied (001_init.sql .. 071_provider_key_agent_use.sql); hand-reviewed, then frozen.
-- Do not edit by hand: change the generator and regenerate.
--
-- 57 tables, 60 indexes, 3 triggers. Needs SQLite >= 3.38.
-- Every statement ends with ';' at end of line (run_migrations splits on it).

CREATE TABLE IF NOT EXISTS schema_migrations (
    version TEXT PRIMARY KEY NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00')
);

CREATE TABLE containers (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    name TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'active',
    root_task_id UUID,
    max_auto_agents INTEGER NOT NULL DEFAULT 12,
    max_tasks INTEGER NOT NULL DEFAULT 200,
    execution_mode TEXT NOT NULL DEFAULT 'human',
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    completed_at TIMESTAMPTZ,
    wakes_enabled BOOLEAN NOT NULL DEFAULT 1,
    llm_api_key_enc TEXT,
    llm_api_key_hint TEXT,
    llm_api_key_set_at TIMESTAMPTZ,
    autonomy_level TEXT NOT NULL DEFAULT 'plan',
    github_repo TEXT,
    last_wake_scan_at TIMESTAMPTZ,
    autonomy_enforced BOOLEAN NOT NULL DEFAULT 0,
    slack_webhook_url TEXT,
    worktrees_disabled BOOLEAN NOT NULL DEFAULT 0,
    icon JSONB,
    review_route TEXT NOT NULL DEFAULT 'manager_chain',
    ai_manager_prereview BOOLEAN NOT NULL DEFAULT 1,
    project_mode TEXT NOT NULL DEFAULT 'code',
    template_key TEXT,
    worktree_auto_cleanup BOOLEAN NOT NULL DEFAULT 1,
    worktree_grace_days INTEGER NOT NULL DEFAULT 7,
    CONSTRAINT containers_autonomy_level_check CHECK ((autonomy_level IN ('plan', 'pr', 'full'))),
    CONSTRAINT containers_project_mode_chk CHECK ((project_mode IN ('code', 'general'))),
    CONSTRAINT containers_review_route_check CHECK ((review_route IN ('manager_chain', 'owner', 'anyone')))
);

CREATE TABLE agent_worktree_inventory (
    container_id UUID PRIMARY KEY NOT NULL,
    host TEXT,
    base_cwd TEXT,
    items JSONB NOT NULL DEFAULT '[]',
    scanned_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_worktree_inventory_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE
);

CREATE TABLE agents (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    container_id UUID NOT NULL,
    alias TEXT NOT NULL,
    role TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'ai',
    system_prompt TEXT,
    status TEXT NOT NULL DEFAULT 'idle',
    is_auto_created BOOLEAN NOT NULL DEFAULT 0,
    parent_agent_id UUID,
    turn_budget INTEGER NOT NULL DEFAULT 50,
    turns_used INTEGER NOT NULL DEFAULT 0,
    last_heartbeat_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    terminated_at TIMESTAMPTZ,
    model TEXT,
    auto_wake_interval_secs INTEGER,
    reasoning_effort TEXT,
    github_login TEXT,
    member_role TEXT NOT NULL DEFAULT 'member',
    grants JSONB NOT NULL DEFAULT '[]',
    git_email TEXT,
    autonomy_override TEXT,
    slack_user_id TEXT,
    reports_to_agent_id UUID,
    CONSTRAINT agents_container_id_alias_key UNIQUE (container_id, alias),
    CONSTRAINT agents_auto_wake_interval_secs_check CHECK (((auto_wake_interval_secs IS NULL) OR (auto_wake_interval_secs >= 60))),
    CONSTRAINT agents_autonomy_override_check CHECK ((autonomy_override IN ('plan', 'pr', 'full'))),
    CONSTRAINT agents_kind_check CHECK ((kind IN ('ai', 'human'))),
    CONSTRAINT agents_member_role_check CHECK ((member_role IN ('owner', 'member', 'viewer'))),
    CONSTRAINT agents_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id),
    CONSTRAINT agents_parent_agent_id_fkey FOREIGN KEY (parent_agent_id) REFERENCES agents(id),
    CONSTRAINT agents_reports_to_agent_id_fkey FOREIGN KEY (reports_to_agent_id) REFERENCES agents(id) ON DELETE SET NULL
);

CREATE TABLE agent_budgets (
    agent_id UUID PRIMARY KEY NOT NULL,
    container_id UUID NOT NULL,
    monthly_limit_usd REAL,
    monthly_limit_tokens INTEGER,
    override_period TEXT,
    override_by UUID,
    override_at TIMESTAMPTZ,
    override_note TEXT,
    warned_period TEXT,
    paused_period TEXT,
    updated_by UUID,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_budgets_monthly_limit_tokens_check CHECK (((monthly_limit_tokens IS NULL) OR (monthly_limit_tokens >= 0))),
    CONSTRAINT agent_budgets_monthly_limit_usd_check CHECK (((monthly_limit_usd IS NULL) OR (monthly_limit_usd >= (0)))),
    CONSTRAINT agent_budgets_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
    CONSTRAINT agent_budgets_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
    CONSTRAINT agent_budgets_override_by_fkey FOREIGN KEY (override_by) REFERENCES agents(id) ON DELETE SET NULL,
    CONSTRAINT agent_budgets_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES agents(id) ON DELETE SET NULL
);

CREATE TABLE agent_config_revisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    agent_id UUID NOT NULL,
    container_id UUID NOT NULL,
    revision_no INTEGER NOT NULL,
    kind TEXT NOT NULL,
    source TEXT NOT NULL,
    snapshot JSONB NOT NULL,
    changes JSONB NOT NULL DEFAULT '[]',
    actor_agent_id UUID,
    actor_kind TEXT,
    actor_alias TEXT,
    restored_from INTEGER,
    reason TEXT,
    redacted_fields JSONB NOT NULL DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_config_revisions_agent_id_revision_no_key UNIQUE (agent_id, revision_no),
    CONSTRAINT agent_config_revisions_actor_kind_check CHECK (((actor_kind IS NULL) OR (actor_kind IN ('human', 'ai')))),
    CONSTRAINT agent_config_revisions_kind_check CHECK ((kind IN ('initial', 'change', 'restore'))),
    CONSTRAINT agent_config_revisions_revision_no_check CHECK ((revision_no >= 1)),
    CONSTRAINT agent_config_revisions_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
    CONSTRAINT agent_config_revisions_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE
);

CREATE TABLE agent_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    container_id UUID,
    target_id UUID,
    event_key TEXT NOT NULL,
    event_name TEXT NOT NULL,
    ts REAL NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_events_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id),
    CONSTRAINT agent_events_target_id_fkey FOREIGN KEY (target_id) REFERENCES agents(id)
);

CREATE TABLE agent_event_acks (
    agent_id UUID NOT NULL,
    event_id INTEGER NOT NULL,
    handled_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    PRIMARY KEY (agent_id, event_id),
    CONSTRAINT agent_event_acks_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
    CONSTRAINT agent_event_acks_event_id_fkey FOREIGN KEY (event_id) REFERENCES agent_events(id) ON DELETE CASCADE
);

CREATE TABLE agent_memory_digests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    container_id UUID NOT NULL,
    agent_id UUID NOT NULL,
    snapshot_ts REAL NOT NULL,
    current_focus TEXT,
    decisions JSONB NOT NULL DEFAULT '[]',
    learnings JSONB NOT NULL DEFAULT '[]',
    open_threads JSONB NOT NULL DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    audience TEXT,
    CONSTRAINT agent_memory_digests_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id),
    CONSTRAINT agent_memory_digests_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id)
);

CREATE TABLE agent_notification_state (
    agent_id UUID PRIMARY KEY NOT NULL,
    read_through_ts REAL NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_notification_state_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE
);

CREATE TABLE agent_reachability (
    agent_id UUID PRIMARY KEY NOT NULL,
    wake_enabled BOOLEAN NOT NULL DEFAULT 1,
    tmux_target TEXT,
    headless_cwd TEXT,
    headless_flags TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT agent_reachability_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id)
);

CREATE TABLE agent_wake_state (
    agent_id UUID PRIMARY KEY NOT NULL,
    delivered_ts REAL NOT NULL DEFAULT 0,
    last_woken_at TIMESTAMPTZ,
    last_wake_kind TEXT,
    last_wake_event TEXT,
    wake_lease_until TIMESTAMPTZ,
    lease_kind TEXT,
    preempt_requested_at TIMESTAMPTZ,
    preempt_for TEXT,
    conv_lease_until TIMESTAMPTZ,
    conv_lease_kind TEXT,
    conv_preempt_requested_at TIMESTAMPTZ,
    conv_preempt_for TEXT,
    conv_delivered_ts REAL,
    conv_last_woken_at TIMESTAMPTZ,
    work_last_heartbeat_at TIMESTAMPTZ,
    conv_last_heartbeat_at TIMESTAMPTZ,
    CONSTRAINT agent_wake_state_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id)
);

CREATE TABLE agent_worktree_actions (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    container_id UUID NOT NULL,
    action TEXT NOT NULL,
    path TEXT,
    branch TEXT,
    keep_branch BOOLEAN NOT NULL DEFAULT 0,
    confirm_unmerged BOOLEAN NOT NULL DEFAULT 0,
    include_output BOOLEAN NOT NULL DEFAULT 1,
    unmerged_paths JSONB NOT NULL DEFAULT '[]',
    status TEXT NOT NULL DEFAULT 'requested',
    requested_by UUID,
    claimed_by TEXT,
    result JSONB,
    error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    claimed_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    CONSTRAINT agent_worktree_actions_action_check CHECK ((action IN ('remove', 'save_output', 'clean_up', 'refresh'))),
    CONSTRAINT agent_worktree_actions_status_check CHECK ((status IN ('requested', 'claimed', 'done', 'failed'))),
    CONSTRAINT agent_worktree_actions_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
    CONSTRAINT agent_worktree_actions_requested_by_fkey FOREIGN KEY (requested_by) REFERENCES agents(id) ON DELETE SET NULL
);

CREATE TABLE container_budgets (
    container_id UUID PRIMARY KEY NOT NULL,
    monthly_limit_usd REAL,
    monthly_limit_tokens INTEGER,
    override_period TEXT,
    override_by UUID,
    override_at TIMESTAMPTZ,
    override_note TEXT,
    warned_period TEXT,
    paused_period TEXT,
    updated_by UUID,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT container_budgets_monthly_limit_tokens_check CHECK (((monthly_limit_tokens IS NULL) OR (monthly_limit_tokens >= 0))),
    CONSTRAINT container_budgets_monthly_limit_usd_check CHECK (((monthly_limit_usd IS NULL) OR (monthly_limit_usd >= (0)))),
    CONSTRAINT container_budgets_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
    CONSTRAINT container_budgets_override_by_fkey FOREIGN KEY (override_by) REFERENCES agents(id) ON DELETE SET NULL,
    CONSTRAINT container_budgets_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES agents(id) ON DELETE SET NULL
);

CREATE TABLE container_github_pat (
    container_id UUID PRIMARY KEY NOT NULL,
    token_enc TEXT NOT NULL,
    token_hint TEXT,
    set_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT container_github_pat_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE
);

CREATE TABLE container_model_settings (
    container_id UUID NOT NULL,
    use_case_key TEXT NOT NULL,
    provider TEXT NOT NULL,
    model TEXT NOT NULL,
    set_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    PRIMARY KEY (container_id, use_case_key),
    CONSTRAINT container_model_settings_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE
);

CREATE TABLE container_provider_keys (
    container_id UUID NOT NULL,
    provider TEXT NOT NULL,
    key_enc TEXT NOT NULL,
    key_hint TEXT,
    set_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    use_for_agents BOOLEAN NOT NULL DEFAULT 0,
    PRIMARY KEY (container_id, provider),
    CONSTRAINT container_provider_keys_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE
);

CREATE TABLE container_verdikt_settings (
    container_id UUID PRIMARY KEY NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT 0,
    base_url TEXT,
    verdikt_project TEXT,
    target_kind TEXT NOT NULL DEFAULT 'web',
    target_locator TEXT,
    trigger_mode TEXT NOT NULL DEFAULT 'manual',
    timeout_minutes INTEGER NOT NULL DEFAULT 30,
    updated_by UUID,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    preview_command TEXT,
    preview_ready_path TEXT NOT NULL DEFAULT '/',
    preview_timeout_seconds INTEGER NOT NULL DEFAULT 120,
    preview_ttl_minutes INTEGER NOT NULL DEFAULT 60,
    autofix_enabled BOOLEAN NOT NULL DEFAULT 0,
    autofix_max_attempts INTEGER NOT NULL DEFAULT 3,
    CONSTRAINT container_verdikt_settings_autofix_max_chk CHECK (((autofix_max_attempts >= 1) AND (autofix_max_attempts <= 10))),
    CONSTRAINT container_verdikt_settings_target_kind_check CHECK ((target_kind IN ('web', 'ios', 'android'))),
    CONSTRAINT container_verdikt_settings_timeout_minutes_check CHECK (((timeout_minutes >= 1) AND (timeout_minutes <= 240))),
    CONSTRAINT container_verdikt_settings_trigger_mode_check CHECK ((trigger_mode IN ('manual', 'ui_changes', 'always'))),
    CONSTRAINT container_verdikt_settings_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
    CONSTRAINT container_verdikt_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES agents(id) ON DELETE SET NULL
);

CREATE TABLE conversations (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    container_id UUID NOT NULL,
    agent_id UUID NOT NULL,
    started_by UUID NOT NULL,
    status TEXT NOT NULL DEFAULT 'active',
    session_id UUID,
    title TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    last_turn_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ,
    session_pinned_at TIMESTAMPTZ,
    CONSTRAINT conversations_status_check CHECK ((status IN ('active', 'idle', 'ended'))),
    CONSTRAINT conversations_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id),
    CONSTRAINT conversations_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id),
    CONSTRAINT conversations_started_by_fkey FOREIGN KEY (started_by) REFERENCES agents(id)
);

CREATE TABLE decisions (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    container_id UUID,
    subject_type TEXT NOT NULL,
    subject_id TEXT NOT NULL,
    decision TEXT NOT NULL,
    reason TEXT,
    actor_agent_id UUID NOT NULL,
    target_agent_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT decisions_decision_check CHECK ((decision IN ('approve', 'reject'))),
    CONSTRAINT decisions_reject_needs_reason CHECK (((decision <> 'reject') OR ((reason IS NOT NULL) AND (length(trim(reason)) > 0)))),
    CONSTRAINT decisions_actor_agent_id_fkey FOREIGN KEY (actor_agent_id) REFERENCES agents(id),
    CONSTRAINT decisions_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id),
    CONSTRAINT decisions_target_agent_id_fkey FOREIGN KEY (target_agent_id) REFERENCES agents(id)
);

CREATE TABLE device_tokens (
    id UUID PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
    container_id UUID NOT NULL,
    agent_id UUID NOT NULL,
    token_hash TEXT NOT NULL,
    label TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    last_used_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    CONSTRAINT device_tokens_token_hash_key UNIQUE (token_hash),
    CONSTRAINT device_tokens_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id),
    CONSTRAINT device_tokens_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id)
);

CREATE TABLE events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    container_id UUID NOT NULL,
    actor_type TEXT NOT NULL,
    actor_id UUID,
    entity_type TEXT NOT NULL,
    entity_id UUID,
    event_type TEXT NOT NULL,
    detail JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT events_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id)
);

CREATE TABLE notification_pref_defaults (
    identity_key TEXT PRIMARY KEY NOT NULL,
    prefs JSONB NOT NULL DEFAULT '{}',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00')
);

CREATE TABLE notification_prefs (
    member_agent_id UUID PRIMARY KEY NOT NULL,
    container_id UUID NOT NULL,
    prefs JSONB NOT NULL DEFAULT '{}',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
    CONSTRAINT notification_prefs_container_id_fkey FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
    CONSTRAINT notification_prefs_member_agent_id_fkey FOREIGN KEY (member_agent_id) REFERENCES agents(id) ON DELETE CASCADE
);

CREATE TABLE plan_usage_display (
