    CONSTRAINT plan_usage_display_id_check CHECK ((id = 1)),
    CONSTRAINT plan_usage_display_providers_check CHECK ((providers IN ('both', 'claude', 'codex')))
);

CREATE TABLE plan_usage_snapshots (
    host TEXT PRIMARY KEY NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    captured_at TIMESTAMPTZ NOT NULL,
